formula.expression:
if(
  empty(prop("Scheduled Window")),
  empty(),
  dateStart(prop("Scheduled Window"))
)

if(
  empty(prop("Scheduled Window")),
  empty(),
  round(
    dateBetween(
      dateEnd(prop("Scheduled Window")),
      dateStart(prop("Scheduled Window")),
      "minutes"
    ) / 60,
    2
  )
)

lets(
  /* Combine all permission names */
  allAccessGroups, concat(
    prop("Can Edit"),
    prop("Can Comment"),
    prop("Can View")
  ).map(current.name()),
  /* Return the broadest group present */
  ifs(
    allAccessGroups.includes("Team"), "Team",
    allAccessGroups.includes("Leadership"), "Leadership",
    allAccessGroups.includes("Owners"), "Owners",
    "Admin"
  )
)

if(
  empty(prop("Scheduled Window")),
  "",
  lets(
    /* Find the Monday belonging to this scheduled week. */
    weekStart,
    dateSubtract(
      dateStart(prop("Scheduled Window")),
      day(dateStart(prop("Scheduled Window"))) - 1,
      "days"
    ),
    /* Thursday determines the correct year at New Year boundaries. */
    isoYear,
    year(dateAdd(weekStart, 3, "days")),
    format(isoYear) + " · Week " +
    if(week(dateStart(prop("Scheduled Window"))) < 10, "0", "") +
    format(week(dateStart(prop("Scheduled Window"))))
  )
)

if(
  empty(prop("Actual Window")),
  empty(),
  round(
    dateBetween(
      dateEnd(prop("Actual Window")),
      dateStart(prop("Actual Window")),
      "minutes"
    ) / 60,
    2
  )
)

if(
  empty(prop("Scheduled Window")) or empty(prop("Actual Window")),
  empty(),
  round(
    (
      dateBetween(
        dateEnd(prop("Actual Window")),
        dateStart(prop("Actual Window")),
        "minutes"
      ) -
      dateBetween(
        dateEnd(prop("Scheduled Window")),
        dateStart(prop("Scheduled Window")),
        "minutes"
      )
    ) / 60,
    2
  )
)
